import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync, readFileSync } from 'node:fs';
import { dirname } from 'node:path';

const stylesheet = readFileSync(new URL('./public/styles.css', import.meta.url));

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(title)} · Workboard</title><link rel="stylesheet" href="/styles.css"></head>
<body><main>${content}</main></body></html>`;
}

const projectFilters = ['Active', 'Archived'];

function readProjectFilter(value) {
  return projectFilters.includes(value) ? value : 'Active';
}

function projectList(projects, filter, error = '') {
  return page('Projects', `<h1>Workboard</h1>
    <form method="post" action="/projects" class="create-form">
      <input type="hidden" name="filter" value="${filter}">
      <label for="project-name">Project name</label>
      <div class="input-group"><input id="project-name" name="name" type="text">
      <button type="submit">Create project</button></div>
    </form>
    ${error ? `<p role="alert" class="alert">${escapeHtml(error)}</p>` : ''}
    <form method="get" action="/" class="project-filter">
      <label for="project-filter">Project filter</label>
      <select id="project-filter" name="filter" onchange="this.form.requestSubmit()">
        ${projectFilters.map((option) => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <section aria-label="Projects" class="project-list">
      ${projects.map((project) => `<div data-testid="project-row" class="project-row">
        <span>${escapeHtml(project.name)}</span>
        <span data-testid="project-summary">${project.completed_count}/${project.total_count} completed</span>
        <form method="get" action="/projects/${project.id}"><button type="submit">Open project</button></form>
        <form method="post" action="/projects/${project.id}/${project.archived ? 'restore' : 'archive'}">
          <button type="submit">${project.archived ? 'Restore project' : 'Archive project'}</button>
        </form>
      </div>`).join('')}
    </section>`);
}

const taskFilters = ['All', 'Open', 'Completed'];

function readTaskFilter(value) {
  return taskFilters.includes(value) ? value : 'All';
}

function projectPath(projectId, filter) {
  return `/projects/${projectId}${filter === 'All' ? '' : `?filter=${filter}`}`;
}

function projectPage(project, tasks, filter, error = '') {
  return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
    ${project.archived ? '<p>Archived project</p>' : ''}
    <form method="get" action="/"><button type="submit">Projects</button></form>
    <form method="post" action="/projects/${project.id}/rename" class="create-form project-rename">
      <input type="hidden" name="filter" value="${filter}">
      <label for="new-project-name">New project name</label>
      <div class="input-group"><input id="new-project-name" name="name" type="text"${project.archived ? ' disabled' : ''}>
      <button type="submit"${project.archived ? ' disabled' : ''}>Rename project</button></div>
    </form>
    <form method="post" action="/projects/${project.id}/tasks" class="create-form task-create">
      <input type="hidden" name="filter" value="${filter}">
      <label for="task-title">Task title</label>
      <div class="input-group"><input id="task-title" name="title" type="text">
      <button type="submit"${project.archived ? ' disabled' : ''}>Create task</button></div>
    </form>
    ${error ? `<p role="alert" class="alert">${escapeHtml(error)}</p>` : ''}
    <form method="get" action="/projects/${project.id}" class="task-filter">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${taskFilters.map((option) => `<option${filter === option ? ' selected' : ''}>${option}</option>`).join('')}
      </select>
    </form>
    <section aria-label="Tasks" class="project-list">
      ${tasks.map((task) => `<div data-testid="task-row" class="task-row">
        <span>${escapeHtml(task.title)}</span>
        <form method="post" action="/projects/${project.id}/tasks/${task.id}/completion">
          <input type="hidden" name="filter" value="${filter}">
          <input type="checkbox" name="completed" value="1" aria-label="${escapeHtml(`Complete ${task.title}`)}"${task.completed ? ' checked' : ''}${project.archived ? ' disabled' : ''} onchange="this.form.requestSubmit()">
        </form>
        <form method="post" action="/projects/${project.id}/tasks/${task.id}/rename" class="task-rename">
          <input type="hidden" name="filter" value="${filter}">
          <label for="new-task-title-${task.id}">New task title</label>
          <div class="input-group"><input id="new-task-title-${task.id}" name="title" type="text"${project.archived ? ' disabled' : ''}>
          <button type="submit"${project.archived ? ' disabled' : ''}>Rename task</button></div>
        </form>
      </div>`).join('')}
    </section>`);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 1024 * 1024) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

export function createWorkboardServer(databasePath) {
  if (databasePath !== ':memory:') mkdirSync(dirname(databasePath), { recursive: true });
  const database = new DatabaseSync(databasePath);
  database.exec(`CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  )`);
  // Existing databases predate archiving; preserve their projects as active.
  if (!database.prepare('PRAGMA table_info(projects)').all().some((column) => column.name === 'archived')) {
    database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
  }
  database.exec(`PRAGMA foreign_keys = ON;
    CREATE TABLE IF NOT EXISTS tasks (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      project_id INTEGER NOT NULL REFERENCES projects(id),
      title TEXT NOT NULL,
      completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
    );
    CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id, id)`);
  const listProjects = database.prepare(`SELECT projects.id, projects.name, projects.archived,
    COUNT(tasks.id) AS total_count, COALESCE(SUM(tasks.completed), 0) AS completed_count
    FROM projects LEFT JOIN tasks ON tasks.project_id = projects.id
    WHERE projects.archived = ? GROUP BY projects.id ORDER BY projects.id`);
  const findProject = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
  const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
  const insertProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
  const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
  const listTasks = database.prepare(`SELECT id, title, completed FROM tasks
    WHERE project_id = ? AND (? IS NULL OR completed = ?) ORDER BY id`);
  const insertTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
  const updateCompletion = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
  const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
  function tasksFor(projectId, filter) {
    const completed = filter === 'All' ? null : Number(filter === 'Completed');
    return listTasks.all(projectId, completed, completed);
  }

  const server = createServer(async (request, response) => {
    function send(status, body, type = 'text/html; charset=utf-8') {
      response.writeHead(status, { 'Content-Type': type });
      response.end(body);
    }
    try {
      const url = new URL(request.url, 'http://localhost');
      if (request.method === 'GET' && url.pathname === '/health') {
        return send(200, JSON.stringify({ status: 'ok' }), 'application/json');
      }
      if (request.method === 'GET' && url.pathname === '/styles.css') {
        return send(200, stylesheet, 'text/css; charset=utf-8');
      }
      if (request.method === 'GET' && url.pathname === '/') {
        const filter = readProjectFilter(url.searchParams.get('filter'));
        return send(200, projectList(listProjects.all(Number(filter === 'Archived')), filter));
      }
      if (request.method === 'POST' && url.pathname === '/projects') {
        const form = await readForm(request);
        const name = (form.get('name') ?? '').trim();
        const filter = readProjectFilter(form.get('filter'));
        if (!name) return send(400, projectList(listProjects.all(Number(filter === 'Archived')), filter, 'Project name is required'));
        insertProject.run(name);
        response.writeHead(303, { Location: '/' });
        return response.end();
      }
      const archiveMatch = /^\/projects\/([1-9]\d*)\/(archive|restore)$/.exec(url.pathname);
      if (request.method === 'POST' && archiveMatch) {
        const id = Number(archiveMatch[1]);
        if (Number.isSafeInteger(id) && findProject.get(id)) {
          const archived = archiveMatch[2] === 'archive';
          updateArchive.run(Number(archived), id);
          response.writeHead(303, { Location: archived ? '/' : '/?filter=Archived' });
          return response.end();
        }
      }
      const match = /^\/projects\/([1-9]\d*)(?:\/rename|\/tasks(?:\/([1-9]\d*)\/(completion|rename))?)?$/.exec(url.pathname);
      if (match) {
        const id = Number(match[1]);
        const project = Number.isSafeInteger(id) ? findProject.get(id) : undefined;
        if (project) {
          if (request.method === 'GET' && url.pathname === `/projects/${id}`) {
            const filter = readTaskFilter(url.searchParams.get('filter'));
            return send(200, projectPage(project, tasksFor(id, filter), filter));
          }
          if (request.method === 'POST' && url.pathname !== `/projects/${id}`) {
            const form = await readForm(request);
            const filter = readTaskFilter(form.get('filter'));
            if (project.archived) {
              return send(409, projectPage(project, tasksFor(id, filter), filter, 'Archived project is read-only'));
            }
            if (url.pathname === `/projects/${id}/rename`) {
              const name = (form.get('name') ?? '').trim();
              if (!name) return send(400, projectPage(project, tasksFor(id, filter), filter, 'Project name is required'));
              renameProject.run(name, id);
            } else if (match[2]) {
              const taskId = Number(match[2]);
              if (!Number.isSafeInteger(taskId)) {
                return send(404, page('Not found', '<h1>Task not found</h1>'));
              }
              let result;
              if (match[3] === 'rename') {
                const title = (form.get('title') ?? '').trim();
                if (!title) return send(400, projectPage(project, tasksFor(id, filter), filter, 'Task title is required'));
                result = renameTask.run(title, taskId, id);
              } else {
                result = updateCompletion.run(Number(form.get('completed') === '1'), taskId, id);
              }
              if (!result.changes) return send(404, page('Not found', '<h1>Task not found</h1>'));
            } else {
              const title = (form.get('title') ?? '').trim();
              if (!title) return send(400, projectPage(project, tasksFor(id, filter), filter, 'Task title is required'));
              insertTask.run(id, title);
            }
            response.writeHead(303, { Location: projectPath(id, filter) });
            return response.end();
          }
        }
      }
      send(404, page('Not found', '<h1>Page not found</h1><a href="/">Projects</a>'));
    } catch (error) {
      if (!error.status) console.error(error);
      send(error.status ?? 500, page('Error', '<h1>Unable to complete request</h1><a href="/">Projects</a>'));
    }
  });
  server.on('close', () => database.close());
  return server;
}
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { join } from 'node:path';
import test from 'node:test';
import { DatabaseSync } from 'node:sqlite';

async function start(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let diagnostics = '';
  child.stderr.on('data', (chunk) => { diagnostics += chunk; });
  const baseUrl = await new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      child.kill();
      reject(new Error(`Server startup timed out: ${diagnostics}`));
    }, 5000);
    child.once('error', (error) => { clearTimeout(timeout); reject(error); });
    child.once('exit', (code) => {
      clearTimeout(timeout);
      reject(new Error(`Server exited (${code}): ${diagnostics}`));
    });
    child.stdout.on('data', (chunk) => {
      const match = /listening on port (\d+)/.exec(String(chunk));
      if (match) {
        clearTimeout(timeout);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    baseUrl,
    async stop() {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

test('task renaming preserves ownership, order, completion, filters, and persisted state through archive and restore', async () => {
  const directory = await mkdtemp(join(process.cwd(), '.workboard-test-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let running;
  try {
    running = await start(databasePath);
    const get = async (path) => (await fetch(`${running.baseUrl}${path}`)).text();
    const post = (path, values = {}) => fetch(`${running.baseUrl}${path}`, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
    await post('/projects', { name: 'First' });
    await post('/projects', { name: 'Second' });
    await post('/projects/1/tasks', { title: 'Done' });
    await post('/projects/1/tasks', { title: 'Pending' });
    await post('/projects/2/tasks', { title: 'Other project task' });
    await post('/projects/1/tasks/1/completion', { completed: '1' });
    const originalPage = await get('/projects/1');
    const otherPage = await get('/projects/2');
    const originalList = await get('/');
    assert.match(originalPage, /<label for="new-task-title-1">New task title<\/label>/);
    assert.match(originalPage, /<input id="new-task-title-1" name="title" type="text">/);
    assert.equal((originalPage.match(/>Rename task<\/button>/g) ?? []).length, 2);
    for (const values of [{}, { title: '' }, { title: ' \t\n ', filter: 'Completed' }]) {
      const response = await post('/projects/1/tasks/1/rename', values);
      assert.equal(response.status, 400);
      const html = await response.text();
      assert.match(html, /role="alert"[^>]*>Task title is required/);
      assert.match(html, /<span>Done<\/span>/);
      assert.match(html, /aria-label="Complete Done" checked/);
      if (values.filter) {
        assert.match(html, /<option selected>Completed<\/option>/);
        assert.doesNotMatch(html, /<span>Pending<\/span>/);
      }
      assert.equal(await get('/projects/1'), originalPage);
    }
    for (const path of ['/projects/2/tasks/1/rename', '/projects/1/tasks/3/rename',
      '/projects/1/tasks/999/rename', '/projects/999/tasks/1/rename']) {
      assert.equal((await post(path, { title: 'Blocked' })).status, 404);
    }
    assert.equal(await get('/projects/1'), originalPage);
    assert.equal(await get('/projects/2'), otherPage);
    const renamed = await post('/projects/1/tasks/1/rename', {
      title: '  Finished <task> "one"  ', filter: 'Completed',
    });
    assert.equal(renamed.status, 303);
    assert.equal(renamed.headers.get('location'), '/projects/1?filter=Completed');
    const openRename = await post('/projects/1/tasks/2/rename', { title: '  Still open  ', filter: 'Open' });
    assert.equal(openRename.status, 303);
    assert.equal(openRename.headers.get('location'), '/projects/1?filter=Open');
    const renamedPage = await get('/projects/1');
    assert.match(renamedPage, /<span>Finished &lt;task&gt; &quot;one&quot;<\/span>/);
    assert.match(renamedPage, /aria-label="Complete Finished &lt;task&gt; &quot;one&quot;" checked/);
    assert.match(renamedPage, /aria-label="Complete Still open" onchange/);
    assert.doesNotMatch(renamedPage, /Complete Done|Complete Pending/);
    assert.ok(renamedPage.indexOf('<span>Finished') < renamedPage.indexOf('<span>Still open'));
    assert.match(renamedPage, /action="\/projects\/1\/tasks\/1\/rename"/);
    assert.equal(await get('/'), originalList);
    assert.equal(await get('/projects/2'), otherPage);
    const completedPage = await get('/projects/1?filter=Completed');
    const openPage = await get('/projects/1?filter=Open');
    assert.match(completedPage, /<span>Finished/);
    assert.doesNotMatch(completedPage, /<span>Still open/);
    assert.match(openPage, /<span>Still open/);
    assert.doesNotMatch(openPage, /<span>Finished/);
    await running.stop();
    running = undefined;
    running = await start(databasePath);
    assert.equal(await get('/projects/1'), renamedPage);
    assert.equal(await get('/projects/1?filter=Completed'), completedPage);
    assert.equal(await get('/projects/1?filter=Open'), openPage);
    assert.equal(await get('/'), originalList);
    await post('/projects/1/archive');
    const archivedPage = await get('/projects/1');
    assert.equal((archivedPage.match(/id="new-task-title-\d+" name="title" type="text" disabled/g) ?? []).length, 2);
    assert.equal((archivedPage.match(/<button type="submit" disabled>Rename task<\/button>/g) ?? []).length, 2);
    assert.equal((await post('/projects/1/tasks/1/rename', { title: 'Blocked' })).status, 409);
    assert.equal(await get('/projects/1'), archivedPage);
    await running.stop();
    running = undefined;
    running = await start(databasePath);
    assert.equal(await get('/projects/1'), archivedPage);
    await post('/projects/1/restore');
    assert.equal(await get('/projects/1'), renamedPage);
    assert.equal(await get('/'), originalList);
    assert.equal((await post('/projects/1/tasks/1/rename', { title: '  Restored title  ' })).status, 303);
    const restoredPage = await get('/projects/1');
    assert.match(restoredPage, /aria-label="Complete Restored title" checked/);
    assert.ok(restoredPage.indexOf('<span>Restored title') < restoredPage.indexOf('<span>Still open'));
    await running.stop();
    running = undefined;
    running = await start(databasePath);
    assert.equal(await get('/projects/1'), restoredPage);
    assert.equal(await get('/'), originalList);
    assert.equal(await get('/projects/2'), otherPage);
  } finally {
    if (running) await running.stop();
    await rm(directory, { recursive: true, force: true });
  }
});

test('renaming preserves project identity, order, tasks, and persisted state; archived projects reject renaming', async () => {
  const directory = await mkdtemp(join(process.cwd(), '.workboard-test-'));
  const databasePath = join(directory, 'workboard.sqlite');
  let running;
  try {
    running = await start(databasePath);
    const get = async (path) => (await fetch(`${running.baseUrl}${path}`)).text();
    const post = (path, values = {}) => fetch(`${running.baseUrl}${path}`, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
    await post('/projects', { name: 'Original' });
    await post('/projects', { name: 'Second' });
    await post('/projects/1/tasks', { title: 'Done' });
    await post('/projects/1/tasks', { title: 'Pending' });
    await post('/projects/1/tasks/1/completion', { completed: '1' });
    const originalPage = await get('/projects/1');
    assert.match(originalPage, /<label for="new-project-name">New project name<\/label>/);
    assert.match(originalPage, /<input id="new-project-name" name="name" type="text">/);
    assert.match(originalPage, /<button type="submit">Rename project<\/button>/);
    for (const values of [{}, { name: '' }, { name: ' \t\n ' }]) {
      const response = await post('/projects/1/rename', values);
      assert.equal(response.status, 400);
      const html = await response.text();
      assert.match(html, /role="alert"[^>]*>Project name is required/);
      assert.match(html, /<h1>Original<\/h1>/);
      assert.equal(await get('/projects/1'), originalPage);
    }
    assert.equal((await post('/projects/999/rename', { name: 'Missing' })).status, 404);
    const renamed = await post('/projects/1/rename', { name: '  Renamed <project> "one"  ', filter: 'Completed' });
    assert.equal(renamed.status, 303);
    assert.equal(renamed.headers.get('location'), '/projects/1?filter=Completed');
    const renamedPage = await get('/projects/1');
    assert.match(renamedPage, /<h1>Renamed &lt;project&gt; &quot;one&quot;<\/h1>/);
    assert.match(renamedPage, /aria-label="Complete Done" checked/);
    assert.match(renamedPage, /aria-label="Complete Pending" onchange/);
    assert.equal((renamedPage.match(/data-testid="task-row"/g) ?? []).length, 2);
    const renamedList = await get('/');
    assert.match(renamedList, /<span>Renamed &lt;project&gt; &quot;one&quot;<\/span>/);
    assert.match(renamedList, /data-testid="project-summary">1\/2 completed/);
    assert.ok(renamedList.indexOf('<span>Renamed') < renamedList.indexOf('<span>Second'));
    assert.match(renamedList, /action="\/projects\/1"/);
    assert.match(await get('/projects/2'), /<h1>Second<\/h1>/);
    await running.stop();
    running = undefined;
    running = await start(databasePath);
    assert.equal(await get('/projects/1'), renamedPage);
    assert.equal(await get('/'), renamedList);
    await post('/projects/1/archive');
    const archivedPage = await get('/projects/1');
    assert.match(archivedPage, /<input id="new-project-name" name="name" type="text" disabled>/);
    assert.match(archivedPage, /<button type="submit" disabled>Rename project<\/button>/);
    const blocked = await post('/projects/1/rename', { name: 'Blocked' });
    assert.equal(blocked.status, 409);
    assert.match(await blocked.text(), /Archived project is read-only/);
    assert.equal(await get('/projects/1'), archivedPage);
    await running.stop();
    running = undefined;
    running = await start(databasePath);
    assert.equal(await get('/projects/1'), archivedPage);
    await post('/projects/1/restore');
    assert.equal(await get('/projects/1'), renamedPage);
    const restoredRename = await post('/projects/1/rename', { name: '  Restored name  ' });
    assert.equal(restoredRename.status, 303);
    assert.equal(restoredRename.headers.get('location'), '/projects/1');
    const restoredPage = await get('/projects/1');
    assert.match(restoredPage, /<h1>Restored name<\/h1>/);
    assert.match(restoredPage, /aria-label="Complete Done" checked/);
    const restoredList = await get('/');
    assert.match(restoredList, /data-testid="project-summary">1\/2 completed/);
    assert.ok(restoredList.indexOf('<span>Restored name') < restoredList.indexOf('<span>Second'));
