  port = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error('Launch timed out')), 5000);
    child.on('error', reject);
    child.stdout.on('data', chunk => {
      const match = /listening on port (\\d+)/.exec(String(chunk));
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
  });
  const response = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: '"'ok' });
  console.log('npm start with PORT and DB_PATH: health check passed');
} finally {
  if (port) {
    // Stop the HTTP server process directly so npm cannot leave a child running.
    const { execFileSync } = await import('node:child_process');
    const descendants = execFileSync('ps', ['-eo', 'pid,ppid,args'], { encoding: 'utf8' });
    const rows = descendants.trim().split('\\n').slice(1).map(line => {
      const match = /"'^'"\\s*(\\d+)\\s+(\\d+)\\s+(.*)"'$/.exec(line);
      return { pid: Number(match[1]), parent: Number(match[2]), command: match[3] };
    });
